INSERT INTO changelog (title, body, created_at) VALUES ('Заявки: вимкнув доставку — тобі не дублюються', 'Якщо в клієнта вимкнені і група, і бот (клієнт → Meta → «Заявки» → «Куди йдуть заявки»), заявки просто пишуться в базу і тобі в Telegram НЕ летять. Тобі приходить тільки коли канал увімкнений, але не спрацював (у групі нема бота, у боті клієнта ніхто не підписаний), або коли сторінка не привʼязана до клієнта. Копію кожної заявки собі можна увімкнути окремо: Конектори → Meta → Заявки → «Копію кожної заявки — мені».', datetime('now'));
